            # Handle GPU errors specifically
            error_msg = str(e).lower()
            if "cuda" in error_msg or "gpu" in error_msg or "memory" in error_msg:
                raise GPUMemoryException(
                    detail=f"GPU error during quick embedding: {str(e)}"
