def _numpy_to_list(array: np.ndarray) -> List[List[float]]:
    """Convert numpy array to list for JSON serialization."""
    if array.ndim == 1:
        return [array.tolist()]
    elif array.ndim == 2:
        return array.tolist()
    else:
        raise ValueError(f"Unsupported array dimensions: {array.ndim}")


@router.post(
    "/compute",
    response_model=SimilarityResponse,
    summary="Compute similarity matrix",
    description="Compute cosine similarity matrix between two sets of texts using the currently loaded model.",
    responses={
