{"content": "apiVersion: ray.io/v1
kind: RayCluster
metadata:
  name: {{ include "embedding-service.clusterName" . }}
  namespace: {{ .Values.cluster.namespace }}
  labels:
    {{- include "embedding-service.labels" . | nindent 4 }}
spec:
  rayVersion: {{ .Values.cluster.rayVersion | quote }}

  # Head node configuration
  headGroupSpec:
    serviceType: {{ .Values.service.type }}
    rayStartParams:
      dashboard-host: '0.0.0.0'
      num-cpus: '0'  # Don't schedule work on head node
      block: 'true'
    template:
      metadata:
        labels:
          {{- include "embedding-service.selectorLabels" . | nindent 10 }}
          ray.io/node-type: head
        {{- with .Values.podAnnotations }}
        annotations:
          {{- toYaml . | nindent 10 }}
        {{- end }}
      spec:
        serviceAccountName: {{ include "embedding-service.serviceAccountName" . }}
        {{- with .Values.image.pullSecrets }}
        imagePullSecrets:
          {{- toYaml . | nindent 10 }}
        {{- end }}
        securityContext:
          {{- toYaml .Values.securityContext | nindent 10 }}
        {{- if .Values.head.deployServe.enabled }}
        initContainers:
        - name: deploy-ray-serve
          image: {{ .Values.head.deployServe.image | default (include "embedding-service.image" .) }}
          imagePullPolicy: {{ include "embedding-service.imagePullPolicy" . }}
          command:
            - python
            - /app/src/ray_serve_deployment.py
          envFrom:
          - configMapRef:
              name: {{ include "embedding-service.fullname" . }}-config
          env:
          - name: RAY_ADDRESS
            value: "auto"
          {{- with .Values.extraEnv }}
          {{- toYaml . | nindent 10 }}
          {{- end }}
          resources:
            requests:
              cpu: "500m"
              memory: "512Mi"
            limits:
              cpu: "1"
              memory: "1Gi"
        {{- end }}
        containers:
        - name: ray-head
          image: {{ include "embedding-service.image" . }}
          imagePullPolicy: {{ include "embedding-service.imagePullPolicy" . }}
          ports:
          - containerPort: 6379
            name: gcs
            protocol: TCP
          - containerPort: 8265
            name: dashboard
            protocol: TCP
          - containerPort: 10001
            name: client
            protocol: TCP
          - containerPort: {{ .Values.service.port }}
            name: serve
            protocol: TCP
          envFrom:
          - configMapRef:
              name: {{ include "embedding-service.fullname" . }}-config
          env:
          - name: RAY_ADDRESS
            value: "auto"
          - name: POD_IP
            valueFrom:
              fieldRef:
                fieldPath: status.podIP
          {{- with .Values.extraEnv }}
          {{- toYaml . | nindent 10 }}
          {{- end }}
          resources:
            {{- toYaml .Values.head.resources | nindent 12 }}
          livenessProbe:
            httpGet:
              path: /
              port: dashboard
            initialDelaySeconds: 30
            periodSeconds: 10
            timeoutSeconds: 5
            failureThreshold: 3
          readinessProbe:
            httpGet:
              path: /
              port: dashboard
            initialDelaySeconds: 15
            periodSeconds: 5
            timeoutSeconds: 3
            failureThreshold: 3
          {{- if .Values.persistence.enabled }}
          volumeMounts:
          - name: ray-storage
            mountPath: {{ .Values.persistence.mountPath }}
          {{- end }}
        {{- if .Values.persistence.enabled }}
        volumes:
        - name: ray-storage
          persistentVolumeClaim:
            claimName: {{ include "embedding-service.fullname" . }}-pvc
        {{- end }}

  # Worker group configuration
  workerGroupSpecs:
  - groupName: {{ .Values.workers.groupName }}
    replicas: {{ .Values.workers.replicas }}
    minReplicas: {{ .Values.workers.minReplicas }}
    maxReplicas: {{ .Values.workers.maxReplicas }}
    rayStartParams:
      num-cpus: {{ .Values.rayServe.numCpusPerReplica | quote }}
      num-gpus: {{ .Values.workers.resources.requests.gpu | quote }}
      block: 'true'
    template:
      metadata:
        labels:
          {{- include "embedding-service.selectorLabels" . | nindent 10 }}
          ray.io/node-type: worker
          ray.io/group: {{ .Values.workers.groupName }}
        {{- with .Values.podAnnotations }}
        annotations:
          {{- toYaml . | nindent 10 }}
        {{- end }}
      spec:
        serviceAccountName: {{ include "embedding-service.serviceAccountName" . }}
        {{- with .Values.image.pullSecrets }}
        imagePullSecrets:
          {{- toYaml . | nindent 10 }}
        {{- end }}
        securityContext:
          {{- toYaml .Values.securityContext | nindent 10 }}
        containers:
        - name: ray-worker
          image: {{ include "embedding-service.image" . }}
          imagePullPolicy: {{ include "embedding-service.imagePullPolicy" . }}
          envFrom:
          - configMapRef:
              name: {{ include "embedding-service.fullname" . }}-config
          env:
          - name: RAY_ADDRESS
            value: "auto"
          - name: CUDA_VISIBLE_DEVICES
            value: "0"
          - name: NVIDIA_VISIBLE_DEVICES
            value: "all"
          - name: POD_IP
            valueFrom:
              fieldRef:
                fieldPath: status.podIP
          {{- with .Values.extraEnv }}
          {{- toYaml . | nindent 10 }}
          {{- end }}
          resources:
            requests:
              cpu: {{ .Values.workers.resources.requests.cpu | quote }}
              memory: {{ .Values.workers.resources.requests.memory | quote }}
              nvidia.com/gpu: {{ .Values.workers.resources.requests.gpu | quote }}
            limits:
              cpu: {{ .Values.workers.resources.limits.cpu | quote }}
              memory: {{ .Values.workers.resources.limits.memory | quote }}
              nvidia.com/gpu: {{ .Values.workers.resources.limits.gpu | quote }}
          {{- if .Values.persistence.enabled }}
          volumeMounts:
          - name: ray-storage
            mountPath: {{ .Values.persistence.mountPath }}
          {{- end }}
        {{- with .Values.workers.nodeSelector }}
        nodeSelector:
          {{- toYaml . | nindent 10 }}
        {{- end }}
        {{- with .Values.workers.tolerations }}
        tolerations:
          {{- toYaml . | nindent 10 }}
        {{- end }}
        {{- if .Values.persistence.enabled }}
        volumes:
        - name: ray-storage
          persistentVolumeClaim:
            claimName: {{ include "embedding-service.fullname" . }}-pvc
        {{- end }}
", "filePath": "/home/electric/workspace/EmbeddingService/helm/embedding-service/templates/raycluster.yaml"}

